using AssetForge.Core.Models;using AssetForge.Infrastructure.Data;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;namespace AssetForge.Web.Pages;public class IndexModel(AssetForgeDbContext db):PageModel{public List<Asset> Recent{get;set;}=[];public int Total,Available,Assigned,Attention;public async Task OnGetAsync(){Total=await db.Assets.CountAsync();Available=await db.Assets.CountAsync(x=>x.Status=="Available");Assigned=await db.Assets.CountAsync(x=>x.Status=="Assigned");var overdue=await db.Assignments.CountAsync(x=>x.ReturnedUtc==null&&x.ExpectedReturnUtc<DateTime.UtcNow);Attention=await db.Assets.CountAsync(x=>x.Status=="Repair"||x.Status=="Lost")+overdue;Recent=await db.Assets.Include(x=>x.Category).Include(x=>x.Location).OrderByDescending(x=>x.CreatedUtc).Take(6).ToListAsync();}}
